(() => {
'use strict';
const clubs=[
 {name:'Racing del Puerto',short:'R',rating:74,ground:'Estadio del Puerto',keeper:{name:'Mateo Rivas',number:1,rating:76},striker:{name:'Tomás Arce',number:9,rating:78},creator:{name:'Nico Salvatierra',number:10,rating:80},winger:{name:'Leo Funes',number:11,rating:76}},
 {name:'Atlético Serrano',short:'A',rating:77,ground:'Campo de la Cumbre',keeper:{name:'Iván Correa',number:1,rating:79},striker:{name:'Bruno Leiva',number:9,rating:81},creator:{name:'Santi Vidal',number:8,rating:78},winger:{name:'Damián Cruz',number:7,rating:78}},
 {name:'Unión del Valle',short:'U',rating:72,ground:'Parque del Valle',keeper:{name:'Ramiro Suárez',number:1,rating:73},striker:{name:'Julián Méndez',number:19,rating:75},creator:{name:'Facundo Gil',number:10,rating:77},winger:{name:'Agustín Paz',number:11,rating:74}},
 {name:'Deportivo Central',short:'D',rating:79,ground:'Estadio Municipal',keeper:{name:'Pablo Acosta',number:13,rating:81},striker:{name:'Esteban Molina',number:9,rating:82},creator:{name:'Matías Roldán',number:10,rating:83},winger:{name:'Benja Núñez',number:17,rating:78}}
];
const tactics={balanced:{name:'Equilibrado',possession:0,attack:0,defence:0,energy:.1},possession:{name:'Posesión',possession:.15,attack:.035,defence:.005,energy:.12},counter:{name:'Contraataque',possession:-.1,attack:.055,defence:.08,energy:.07},press:{name:'Presión alta',possession:.06,attack:.045,defence:.025,energy:.29}};
const $=id=>document.getElementById(id), teamSelect=$('team-select'), opponentSelect=$('opponent-select');
const state={home:0,away:1,tactic:'balanced',phase:'setup',minute:0,stoppage:0,score:[0,0],stats:null,energy:100,attackSide:0,zone:50,added:0,pending:false,sound:false,audio:null};
const rand=(a,b)=>Math.random()*(b-a)+a, pick=a=>a[Math.floor(Math.random()*a.length)], clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function initSelects(){clubs.forEach((c,i)=>{const a=document.createElement('option'),b=document.createElement('option');a.value=b.value=i;a.textContent=b.textContent=c.name;teamSelect.append(a);opponentSelect.append(b)});teamSelect.value='0';opponentSelect.value='1';teamSelect.addEventListener('change',()=>{if(teamSelect.value===opponentSelect.value)opponentSelect.value=String((+teamSelect.value+1)%clubs.length)});opponentSelect.addEventListener('change',()=>{if(teamSelect.value===opponentSelect.value)teamSelect.value=String((+opponentSelect.value+1)%clubs.length)});}
function addEvent(text,tag='',kind=''){const row=document.createElement('div');row.className=`feed-event ${kind}`;row.innerHTML=`<div class="event-minute">${clockText()}</div><div class="event-copy">${tag?`<span class="event-tag">${tag}</span>`:''}${text}</div>`;$('commentary-feed').prepend(row);}
function clockText(){if(state.phase==='setup')return '—';if(state.minute>90)return `90+${state.minute-90}`;return `${state.minute}'`}
function initStats(){return {possession:[0,0],shots:[0,0],onTarget:[0,0],passes:[0,0],passAtt:[0,0],corners:[0,0],fouls:[0,0],yellow:[0,0],saves:[0,0],xg:[0,0]}}
function setTactic(key){if(!tactics[key])return;state.tactic=key;document.querySelectorAll('[data-tactic]').forEach(b=>b.classList.toggle('selected',b.closest('.tactic-options')&&b.dataset.tactic===key));document.querySelectorAll('#live-tactic-list [data-tactic]').forEach(b=>b.classList.toggle('active',b.dataset.tactic===key));$('current-tactic-name').textContent=tactics[key].name.toUpperCase();}
