function playTone(freq){if(!state.sound)return;try{state.audio=state.audio||new(window.AudioContext||window.webkitAudioContext)();const osc=state.audio.createOscillator(),gain=state.audio.createGain();osc.frequency.value=freq;gain.gain.setValueAtTime(.035,state.audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,state.audio.currentTime+.35);osc.connect(gain);gain.connect(state.audio.destination);osc.start();osc.stop(state.audio.currentTime+.35)}catch(e){}}

