function tick(){if(state.pending||state.phase!=='live')return;if(state.minute===45){state.phase='half';$('match-status').textContent='DESCANSO';$('live-label').textContent='DESCANSO';$('advance-button').innerHTML='<span>Empezar el segundo tiempo</span><span class="button-arrow">▶</span>';addEvent(`<strong>Descanso en ${sideName(0)}.</strong> Los equipos se marchan a vestuarios con ${state.score[0]}–${state.score[1]} en el marcador. Ajusta tu táctica y vuelve al campo.`,'DESCANSO','highlight');renderStats();return;}if(state.minute===90){if(!state.added){state.added=3+Math.floor(Math.random()*3);addEvent(`El cuarto árbitro indica <strong>${state.added} minutos de añadido.</strong>`,'TIEMPO AÑADIDO')}if(state.minute>=90+state.added){finishMatch();return;}}
 state.minute++;state.attackSide=choosePossession();const side=state.attackSide,tac=tactics[state.tactic];state.energy=clamp(state.energy-(tac.energy*(side===0?1:.45))-(Math.random()*.045),29,100);sCurrentPossession(side);let zone;if(side===0)zone=rand(17,91);else zone=100-rand(17,91);setBall(zone);const team=clubs[side===0?state.home:state.away],opp=clubs[side===0?state.away:state.home];let eventMade=false;
 if(Math.random()<.033){const fouled=side===0?onField(1,'creator'):onField(0,'creator');state.stats.fouls[1-side]++;if(Math.random()<.22){state.stats.yellow[1-side]++;addEvent(`Falta táctica sobre ${fouled.name}. El árbitro amonesta al jugador; no dejará pasar otra.`,'TARJETA','highlight')}else addEvent(`Falta sobre ${fouled.name}. El árbitro detiene el juego y señala tiro libre.`,'FALTA');eventMade=true;}
 const progression=side===0?(state.zone>62):(state.zone<38);const chanceBase=side===0?.12:.115;const chance=chanceBase+(side===0?tac.attack:0)+(side===0&&state.tactic==='counter'&&state.stats.possession[1]>state.stats.possession[0]?.025:0);if(progression&&Math.random()<chance){if(side===0){addEvent(`<strong>${onField(0,'creator').name} recibe en una zona peligrosa.</strong> ${onField(0,'striker').name} se mueve entre los centrales y se abre una opción de ataque.`,'PUEDE PASAR','highlight');attackDecision();return;}const shooter=onField(1,'striker'),xg=rand(.075,.3)*(1+tac.attack)*(state.energy/100);addEvent(`<strong>${team.name} encuentra espacio en el último tercio.</strong> ${onField(1,'creator').name} habilita a ${shooter.name}.`,'PELIGRO','highlight');takeShot(1,xg,shooter);eventMade=true;}
