 if(!eventMade){const stories=side===0?[`${onField(0,'creator').name} pide la pelota y cambia la orientación del juego.`,`${team.name} mueve el balón con paciencia; el rival cierra los espacios.`,`${onField(0,'winger').name} recibe pegado a la banda y busca apoyo.`,`Buen cierre de ${onField(1,'creator').name}; el avance local no encuentra continuidad.`]:[`${team.name} intenta progresar por el centro, pero el bloque local está bien plantado.`,`${onField(1,'creator').name} conduce unos metros y descarga con seguridad.`,`El equipo visitante gana la segunda pelota y vuelve a empezar desde atrás.`,`Presiona ${onField(0,'creator').name}; el rival debe jugar largo.`];addEvent(pick(stories),side===0?'RACING':'VISITANTE');}
